from collections import deque

def is_bipartite(n, graph):
    color = {}
    for start in range(n):
        if start in color:
            continue
        color[start] = 0
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in color:
                    color[neighbor] = 1 - color[node]   # opposite color
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False                          # same-colored edge found
    return True
```

The outer `for start in range(n)` is doing double duty here: it's both the connected-components pattern (checking every component, not just the first) and the guarantee that a disconnected graph's other pieces get checked too.
